script:
(function () {
  'use strict';
  // Fibonacci retracement and extension levels for a swing between a low and a high.
  //   range = high - low
  //   Uptrend (low first, then high):
  //     retracement p%  = high - range x p     (0% = the high, 100% = the low)
  //     extension   p%  = low  + range x p     (measured from the swing start; 100% = the high)
  //   Downtrend (high first, then low):
  //     retracement p%  = low  + range x p     (0% = the low, 100% = the high)
  //     extension   p%  = high - range x p     (100% = the low)
  // Ratios: 23.6 / 38.2 / 61.8 / 78.6 come from the Fibonacci ratio 0.618 and its powers
  // (0.618^2 = 0.382, 0.618^3 = 0.236, sqrt(0.618) = 0.786); 50% is the conventional midpoint.
  // Verified (scratch Node test): high 150, low 100, uptrend -> 38.2% = 130.90, 61.8% = 119.10,
  // 161.8% extension = 180.90; downtrend -> 61.8% = 130.90, 161.8% extension = 69.10.
  // An extension below zero is shown as "Below 0" rather than as a negative price.
  var RETRACEMENTS = [0, 23.6, 38.2, 50, 61.8, 78.6, 100];
  var EXTENSIONS = [127.2, 161.8, 200, 261.8, 361.8, 423.6];

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function decimalsOf(id) {
    var el = document.getElementById(id);
    var s = el ? String(el.value || '') : '';
    var i = s.indexOf('.');
    return i < 0 ? 0 : Math.min(6, s.length - i - 1);
  }
  function fmt(v, dp) {
    if (!isFinite(v)) return '–';
    return v.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
  }
  function pctLabel(p) { return (Math.round(p * 10) / 10).toFixed(1) + '%'; }

  function level(high, low, up, p, kind) {
    var range = high - low, f = p / 100;
    if (kind === 'ret') return up ? high - range * f : low + range * f;
    return up ? low + range * f : high - range * f;
  }

  function rowsHtml(list, high, low, up, kind, dp, current) {
    return list.map(function (p) {
      var price = level(high, low, up, p, kind);
      var priceText = price < 0 ? 'Below 0' : fmt(price, dp);
      var dist = '–';
      if (isFinite(current) && current > 0 && price >= 0) {
        var d = (price - current) / current * 100;
        dist = (d > 0 ? '+' : '') + d.toFixed(2) + '%';
      }
      return '<tr><td>' + pctLabel(p) + '</td><td>' + priceText + '</td><td>' + dist + '</td></tr>';
    }).join('');
  }

  function withCustom(list, custom) {
    if (!isFinite(custom) || list.indexOf(custom) >= 0) return list;
    return list.concat([custom]).sort(function (a, b) { return a - b; });
  }

  function clear() {
    ['fibRange', 'fibHalf', 'fibGolden', 'fibExt'].forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('fibRetTable').innerHTML = '';
    document.getElementById('fibExtTable').innerHTML = '';
  }

  function update() {
    var high = num('fibHigh'), low = num('fibLow'), up = document.getElementById('fibTrend').value === 'up';
    var currentRaw = document.getElementById('fibCurrent').value, current = num('fibCurrent');
    var customRaw = document.getElementById('fibCustom').value, custom = num('fibCustom');
    var error = document.getElementById('fibError');
    var msg = '';
    if (isNaN(high) || isNaN(low)) msg = 'Enter both the swing high and the swing low.';
    else if (low < 0) msg = 'Prices cannot be negative.';
    else if (high <= low) msg = 'The swing high must be above the swing low.';
    else if (String(currentRaw).trim() !== '' && (isNaN(current) || current <= 0)) msg = 'Current price must be above 0, or leave it blank.';
    else if (String(customRaw).trim() !== '' && (isNaN(custom) || custom < 0 || custom > 1000)) msg = 'Custom level must be from 0% to 1,000%, or leave it blank.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }
    if (String(customRaw).trim() === '') custom = NaN;
    if (String(currentRaw).trim() === '') current = NaN;

    var dp = Math.max(2, decimalsOf('fibHigh'), decimalsOf('fibLow'));
    var range = high - low;
    // Size of the move as a % of its starting price: a rise from the low, or a fall from the high.
    var movePct = up ? (low > 0 ? range / low * 100 : NaN) : -range / high * 100;
    document.getElementById('fibRange').textContent = fmt(range, dp) +
      (isFinite(movePct) ? ' (' + (movePct > 0 ? '+' : '') + movePct.toFixed(2) + '%)' : '');
    document.getElementById('fibHalf').textContent = fmt(level(high, low, up, 50, 'ret'), dp);
    document.getElementById('fibGolden').textContent = fmt(level(high, low, up, 61.8, 'ret'), dp);
    var ext = level(high, low, up, 161.8, 'ext');
    document.getElementById('fibExt').textContent = ext < 0 ? 'Below 0' : fmt(ext, dp);
    var retList = custom <= 100 ? withCustom(RETRACEMENTS, custom) : RETRACEMENTS;
    var extList = custom > 100 ? withCustom(EXTENSIONS, custom) : EXTENSIONS;
    document.getElementById('fibRetTable').innerHTML = rowsHtml(retList, high, low, up, 'ret', dp, current);
    document.getElementById('fibExtTable').innerHTML = rowsHtml(extList, high, low, up, 'ext', dp, current);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('fibForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
